### C++

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <regex>
#include <iomanip>
using namespace std;

// 提取字符串中的所有数值（整数或浮点数，支持负号）
vector<double> extractNumbers(const string& s) {
    vector<double> res;
    regex re("-?\\d+(\\.\\d+)?");
    auto it_begin = sregex_iterator(s.begin(), s.end(), re);
    auto it_end = sregex_iterator();
    for (auto it = it_begin; it != it_end; ++it) {
        res.push_back(stod(it->str()));
    }
    return res;
}

int main() {
    string line1, line2;
    getline(cin, line1);
    getline(cin, line2);

    // 解析第一行
    vector<double> values1 = extractNumbers(line1);
    int N = values1.size() / 3;
    vector<vector<double>> X(N, vector<double>(2));
    vector<int> y(N);
    for (int i = 0; i < N; ++i) {
        X[i][0] = values1[i * 3];
        X[i][1] = values1[i * 3 + 1];
        y[i] = (int)round(values1[i * 3 + 2]);
    }

    // 解析第二行
    vector<double> values2 = extractNumbers(line2);
    int epoch = (int)round(values2[0]);
    double lr = values2[1];

    double w1 = 0.0, w2 = 0.0, b = 0.0;

    for (int e = 0; e < epoch; ++e) {
        double sum_w1 = 0.0, sum_w2 = 0.0, sum_b = 0.0;
        for (int i = 0; i < N; ++i) {
            double score = w1 * X[i][0] + w2 * X[i][1] + b;
            if (y[i] * score <= 0) {
                sum_w1 += y[i] * X[i][0];
                sum_w2 += y[i] * X[i][1];
                sum_b  += y[i];
            }
        }
        w1 += lr * sum_w1;
        w2 += lr * sum_w2;
        b  += lr * sum_b;
    }

    cout << fixed << setprecision(3);
    cout << "[" << w1 << ", " << w2 << ", " << b << "]" << endl;

    return 0;
}
